// Clive's round satellite: the UI logic that is easier in C++ than in YAML.
// The widgets are declared in ui.yaml (generated by tools/gen_ui.py); gen_ui.py also emits the lambda that fills `clive::w`.
// Design and numbers come from docs/CLIVE-STYLE.md and satellite/design/flows.html.
#pragma once
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include "lvgl.h"
#include "clive_icons.h"

namespace clive {

constexpr int SCREEN = 800;
constexpr float U = SCREEN / 280.0f;   // one unit of the 280-unit layout the apps use, in px

enum State { IDLE = 0, LISTEN = 1, THINK = 2, SPEAK = 3 };
enum Design { GLANCE = 0, CLOCK = 1, WEATHER = 2, RING = 3 };

struct Widgets {
  // layers
  lv_obj_t *glow = nullptr, *blob[3] = {nullptr, nullptr, nullptr}, *vignette = nullptr;
  lv_obj_t *idle[4] = {nullptr, nullptr, nullptr, nullptr};
  lv_obj_t *card = nullptr, *dock = nullptr, *shade = nullptr, *menu = nullptr, *pair = nullptr;
  lv_obj_t *mark[4] = {nullptr, nullptr, nullptr, nullptr};   // idle, listen, think, speak
  // idle labels
  lv_obj_t *time_label[4] = {nullptr, nullptr, nullptr, nullptr};   // the clock of each design
  lv_obj_t *date_label[4] = {nullptr, nullptr, nullptr, nullptr};   // the date (short) of each design
  lv_obj_t *glance_date = nullptr, *glance_out = nullptr, *glance_in = nullptr;
  lv_obj_t *clock_temp = nullptr, *clock_icon = nullptr;
  lv_obj_t *weather_icon = nullptr, *weather_temp = nullptr, *weather_cond = nullptr, *weather_hl = nullptr, *weather_small_time = nullptr, *weather_small_date = nullptr;
  lv_obj_t *ring_date = nullptr, *ring_sec = nullptr, *ring_hour = nullptr;
  lv_obj_t *g_icon[3] = {nullptr, nullptr, nullptr}, *g_value[3] = {nullptr, nullptr, nullptr}, *g_label[3] = {nullptr, nullptr, nullptr};
  // card
  lv_obj_t *card_icon = nullptr, *card_big = nullptr, *card_title = nullptr, *card_sub = nullptr, *card_row[3] = {nullptr, nullptr, nullptr};
  lv_obj_t *card_bar = nullptr, *card_yes = nullptr, *card_no = nullptr, *card_stack = nullptr;
  // quick settings
  lv_obj_t *qs_volume = nullptr, *qs_bright = nullptr, *tile[5] = {nullptr, nullptr, nullptr, nullptr, nullptr}, *pair_qr = nullptr, *pair_code = nullptr;
};
inline Widgets w;

struct Info {
  std::string outside = "12°", cond = "cloudy", high = "14°", low = "8°", inside = "19°";
  std::string g_home = "2 of 4", g_energy = "24p", g_car = "80%", g_alarm = "Home", g_heat = "19°", g_air = "Good";
};
inline Info info;

struct Glance { const char *key, *icon, *label; };
inline const Glance GLANCES[] = {
    {"Who's home", ICON_ACCOUNT_MULTIPLE, "home"}, {"Electricity", ICON_LIGHTNING_BOLT, "per kWh"}, {"Car charge", ICON_CAR_ELECTRIC, "car"},
    {"Alarm", ICON_SHIELD_CHECK, "alarm"}, {"Heating", ICON_RADIATOR, "heating"}, {"Air quality", ICON_AIR_FILTER, "air"}, {"Forecast", ICON_WEATHER_CLOUDY, "outside"}};
constexpr int GLANCE_COUNT = 7;

inline int design = GLANCE;
inline int glance_slot[3] = {0, 1, 2};
inline int state = IDLE;
inline bool card_on = false;
inline bool shade_open = false;
inline float shade_pull = 0, glow_alpha = 0, glow_speed = 0.6f, glow_phase = 0, glow_pulse = 0, card_fade = 0;
inline float level = 0.3f;
inline int mark_shown = -1;
inline float col_cur[3][3] = {{0x5C, 0x6B, 0xC0}, {0xAB, 0x47, 0xBC}, {0x4F, 0xD0, 0x8A}};
inline float col_tgt[3][3] = {{0x5C, 0x6B, 0xC0}, {0xAB, 0x47, 0xBC}, {0x4F, 0xD0, 0x8A}};
inline lv_grad_dsc_t grads[3];
inline lv_style_t *st_dim = nullptr, *st_faint = nullptr, *st_soft = nullptr;
inline bool screen_dirty = true;
inline int wake_ms = 0;   // time since the screen last changed, for the night dimming

inline float approach(float cur, float tgt, float dt, float tau) { return cur + (tgt - cur) * (1.0f - std::exp(-dt / tau)); }
inline float clampf(float v, float a, float b) { return v < a ? a : (v > b ? b : v); }

inline void hide(lv_obj_t *o, bool h) {
  if (!o) return;
  if (h) lv_obj_add_flag(o, LV_OBJ_FLAG_HIDDEN);
  else lv_obj_remove_flag(o, LV_OBJ_FLAG_HIDDEN);
}
inline void text(lv_obj_t *o, const std::string &s) {
  if (!o) return;
  if (s != lv_label_get_text(o)) lv_label_set_text(o, s.c_str());
}

// The condition's Material Design icon (the weather entity's state).
inline const char *weather_icon(const std::string &c) {
  if (c == "sunny" || c == "clear-day") return ICON_WEATHER_SUNNY;
  if (c == "clear-night") return ICON_WEATHER_NIGHT;
  if (c == "partlycloudy") return ICON_WEATHER_PARTLY_CLOUDY;
  if (c == "rainy" || c == "pouring") return ICON_WEATHER_RAINY;
  if (c == "snowy" || c == "snowy-rainy") return ICON_WEATHER_SNOWY;
  if (c == "lightning" || c == "lightning-rainy") return ICON_WEATHER_LIGHTNING;
  if (c == "fog") return ICON_WEATHER_FOG;
  if (c == "windy" || c == "windy-variant") return ICON_WEATHER_WINDY;
  return ICON_WEATHER_CLOUDY;
}
inline std::string weather_words(const std::string &c) {
  if (c == "sunny") return "Sunny";
  if (c == "clear-night") return "Clear";
  if (c == "partlycloudy") return "Partly cloudy";
  if (c == "rainy") return "Rainy";
  if (c == "pouring") return "Pouring";
  if (c == "snowy") return "Snowy";
  if (c == "lightning" || c == "lightning-rainy") return "Thunder";
  if (c == "fog") return "Foggy";
  if (c == "windy") return "Windy";
  return "Cloudy";
}

inline const char *glance_value(int key) {
  switch (key) {
    case 0: return info.g_home.c_str();
    case 1: return info.g_energy.c_str();
    case 2: return info.g_car.c_str();
    case 3: return info.g_alarm.c_str();
    case 4: return info.g_heat.c_str();
    case 5: return info.g_air.c_str();
    default: return info.outside.c_str();
  }
}

// ---------------------------------------------------------------- what is shown where
inline void show_layers() {
  bool talking = state != IDLE;
  bool glow_on = talking && state != IDLE;
  hide(w.glow, !(glow_on || glow_alpha > 0.01f));
  for (int i = 0; i < 4; i++) hide(w.idle[i], !(i == design && !card_on));
  hide(w.card, !card_on);
  // idle layer reads over the glow: lighter greys while it is on
  if (st_dim && st_faint && st_soft) {
    lv_style_set_text_color(st_dim, lv_color_hex(talking ? 0xD2D6EA : 0x9096B0));
    lv_style_set_text_color(st_faint, lv_color_hex(talking ? 0xB4B9D2 : 0x5A6078));
    lv_style_set_text_color(st_soft, lv_color_hex(talking ? 0xF2F3FF : 0xE8EAFF));
    lv_obj_report_style_change(NULL);
  }
}

inline void update_info_labels() {
  text(w.glance_out, info.outside + " out");
  text(w.glance_in, info.inside + " in");
  text(w.clock_temp, info.outside);
  text(w.clock_icon, weather_icon(info.cond));
  text(w.weather_icon, weather_icon(info.cond));
  text(w.weather_temp, info.outside);
  text(w.weather_cond, weather_words(info.cond));
  text(w.weather_hl, "H " + info.high + " · L " + info.low);
  for (int i = 0; i < 3; i++) {
    const Glance &g = GLANCES[glance_slot[i]];
    text(w.g_icon[i], glance_slot[i] == 6 ? weather_icon(info.cond) : g.icon);
    text(w.g_value[i], glance_value(glance_slot[i]));
    text(w.g_label[i], g.label);
  }
}

inline void update_time(int hour, int minute, int second, const char *date_short, const char *date_ring) {
  char hm[8];
  std::snprintf(hm, sizeof hm, "%02d:%02d", hour, minute);
  for (int i = 0; i < 4; i++) text(w.time_label[i], hm);
  text(w.weather_small_time, hm);
  text(w.glance_date, date_short);
  text(w.date_label[CLOCK], date_short);
  text(w.weather_small_date, std::string(" · ") + date_short);
  text(w.ring_date, std::string(date_ring) + " · " + info.outside);
  if (w.ring_sec) lv_arc_set_value(w.ring_sec, second);
  if (w.ring_hour) lv_arc_set_value(w.ring_hour, ((hour % 12) * 60 + minute));
}

// ---------------------------------------------------------------- the glow
inline void set_palette(uint32_t a, uint32_t b, uint32_t c) {
  uint32_t cs[3] = {a, b, c};
  for (int i = 0; i < 3; i++) {
    col_tgt[i][0] = (cs[i] >> 16) & 0xFF;
    col_tgt[i][1] = (cs[i] >> 8) & 0xFF;
    col_tgt[i][2] = cs[i] & 0xFF;
  }
}
inline void base_palette() { set_palette(0x5C6BC0, 0xAB47BC, 0x4FD08A); }

inline void draw_blob_gradient(int i, float alpha) {
  lv_color_t c = lv_color_make((uint8_t) col_cur[i][0], (uint8_t) col_cur[i][1], (uint8_t) col_cur[i][2]);
  lv_color_t cols[2] = {c, c};
  lv_opa_t opa[2] = {(lv_opa_t) (clampf(alpha, 0, 1) * 255), 0};
  uint8_t fr[2] = {0, 255};
  lv_grad_init_stops(&grads[i], cols, opa, fr, 2);
  lv_grad_radial_init(&grads[i], LV_PCT(50), LV_PCT(50), LV_PCT(100), LV_PCT(50), LV_GRAD_EXTEND_PAD);
  lv_obj_set_style_bg_grad(w.blob[i], &grads[i], 0);
}

// ---------------------------------------------------------------- one UI step (about every 60 ms)
inline void tick(float dt) {
  const float tau_alpha = 0.17f, tau_col = 0.47f;
  static const float INT_BRIGHT[4] = {0.72f, 1.0f, 0.92f, 0.95f}, INT_SPEED[4] = {0.6f, 1.6f, 4.2f, 2.4f};
  bool glow_on = state != IDLE;
  glow_alpha = approach(glow_alpha, glow_on ? INT_BRIGHT[state] : 0.0f, dt, tau_alpha);
  float speed = INT_SPEED[state];
  glow_speed = approach(glow_speed, speed, dt, 0.2f);
  glow_phase += dt * 360.0f / 16.0f * glow_speed;
  glow_pulse += dt;
  if (glow_phase > 36000.0f) glow_phase -= 36000.0f;

  bool changed = false;
  for (int i = 0; i < 3; i++)
    for (int k = 0; k < 3; k++) {
      float v = approach(col_cur[i][k], col_tgt[i][k], dt, tau_col);
      if (std::fabs(v - col_cur[i][k]) > 0.05f) changed = true;
      col_cur[i][k] = v;
    }
  float extra = state == LISTEN ? (level - 0.25f) * 0.25f : (state == SPEAK ? std::sin(glow_pulse * 9.0f) * 0.07f : 0.0f);
  float a = clampf(glow_alpha + extra, 0.0f, 1.0f);
  if (glow_alpha > 0.01f && w.glow) {
    const float m = SCREEN, rf[3] = {0.28f, 0.28f, 0.30f};
    const float ang[3] = {glow_phase + 210.0f, -glow_phase * 1.3f + 330.0f, glow_phase * 0.8f + 90.0f};
    for (int i = 0; i < 3; i++) {
      float r = ang[i] * 3.14159265f / 180.0f;
      int cx = SCREEN / 2 + (int) (m * rf[i] * std::cos(r)), cy = SCREEN / 2 + (int) (m * rf[i] * std::sin(r));
      int rad = (int) (m * 0.62f);
      lv_obj_set_pos(w.blob[i], cx - rad, cy - rad);
      draw_blob_gradient(i, a);
    }
  }
  (void) changed;
  hide(w.glow, glow_alpha <= 0.01f && !glow_on);

  // the dock's mark: one animation per pose, only the current one shown
  int pose = state == LISTEN ? 1 : (state == THINK ? 2 : (state == SPEAK ? 3 : 0));
  if (pose != mark_shown) {
    for (int i = 0; i < 4; i++) hide(w.mark[i], i != pose);
    mark_shown = pose;
  }
  // the quick-settings shade slides down from the top
  shade_pull = approach(shade_pull, shade_open ? 1.0f : 0.0f, dt, 0.1f);
  if (w.shade) {
    lv_obj_set_y(w.shade, (int) ((shade_pull - 1.0f) * SCREEN));
    hide(w.shade, shade_pull < 0.002f);
  }
}

inline void set_state(int s) {
  if (s == state) return;
  state = s;
  show_layers();
}

// ---------------------------------------------------------------- cards
inline void card_hide() {
  card_on = false;
  base_palette();
  show_layers();
}
// icon: a UTF-8 icon string from the icon table; rows and the bar are optional ("" hides). percent < 0 hides the bar.
inline void card_show(const char *icon, const std::string &big, const std::string &title, const std::string &sub, const std::string &r1,
                      const std::string &r2, const std::string &r3, int percent, bool ask, uint32_t c1, uint32_t c2, uint32_t c3) {
  text(w.card_icon, icon);
  hide(w.card_icon, icon[0] == 0);
  auto set = [](lv_obj_t *o, const std::string &s) { text(o, s); hide(o, s.empty()); };
  set(w.card_big, big);
  set(w.card_title, title);
  set(w.card_sub, sub);
  // keep the stack within the glass: with a big figure, a title and a sub line, two rows at most
  std::string rr[3] = {r1, r2, r3};
  int lines = (big.empty() ? 0 : 3) + (title.empty() ? 0 : 1) + (sub.empty() ? 0 : 1);
  int room = lines >= 5 ? 2 : (lines >= 4 ? 3 : 3);
  for (int i = 0; i < 3; i++) set(w.card_row[i], i < room ? rr[i] : std::string());
  if (w.card_bar) {
    hide(w.card_bar, percent < 0);
    if (percent >= 0) lv_bar_set_value(w.card_bar, percent, LV_ANIM_OFF);
  }
  hide(w.card_yes, !ask);
  hide(w.card_no, !ask);
  set_palette(c1, c2, c3);
  card_on = true;
  show_layers();
}


// ---------------------------------------------------------------- touch, menu, pairing
inline int touch_y0 = -1;
inline std::string device_name = "clive-round";
inline int pointer_y() {
  lv_indev_t *i = lv_indev_active();
  if (!i) return -1;
  lv_point_t p;
  lv_indev_get_point(i, &p);
  return p.y;
}
inline void touch_down() { touch_y0 = pointer_y(); }
// A swipe down from the top edge opens quick settings; a swipe up closes it; a tap on a card puts the clock back.
inline void touch_up(bool in_shade) {
  int y = pointer_y();
  if (touch_y0 < 0 || y < 0) return;
  int dy = y - touch_y0;
  bool overlay = (w.menu && !lv_obj_has_flag(w.menu, LV_OBJ_FLAG_HIDDEN)) || (w.pair && !lv_obj_has_flag(w.pair, LV_OBJ_FLAG_HIDDEN));
  if (!in_shade && !overlay && touch_y0 < (int) (U * 62) && dy > (int) (U * 30)) shade_open = true;
  else if (in_shade && dy < -(int) (U * 30)) shade_open = false;
  else if (!in_shade && card_on && std::abs(dy) < 30 && !(w.card_yes && !lv_obj_has_flag(w.card_yes, LV_OBJ_FLAG_HIDDEN))) card_hide();
  touch_y0 = -1;
}
inline void on_dock_tap() {}
inline void open_menu() {
  shade_open = false;
  hide(w.menu, false);
}
// Pairing is open while the pair screen is up (and for 2 minutes at most). The Wi-Fi hand-over over Bluetooth (improv_ble) only accepts a
// phone while this is true, so someone near the house cannot change the Wi-Fi of a satellite whose screen is not showing the code.
inline uint32_t pair_until = 0;
inline bool pairing_open() { return pair_until != 0 && (int32_t) (pair_until - esphome::millis()) > 0; }
inline void close_menu() {
  hide(w.menu, true);
  hide(w.pair, true);
  pair_until = 0;
}
inline void show_pair() {
  // A single-use token, shown as a QR code and as six digits. The companion app scans it (docs/SATELLITE-PAIRING.md).
  char code[8], uri[96];
  std::snprintf(code, sizeof code, "%06u", (unsigned) (esphome::random_uint32() % 1000000));
  std::snprintf(uri, sizeof uri, "clive://pair?d=%s&t=%s", device_name.c_str(), code);
  if (w.pair_qr) lv_qrcode_update(w.pair_qr, uri, std::strlen(uri));
  std::string spaced = std::string(code, 3) + " " + std::string(code + 3, 3);
  text(w.pair_code, device_name + " · code " + spaced);
  hide(w.menu, true);
  hide(w.pair, false);
  pair_until = esphome::millis() + 120000u;
}
inline void on_menu(int i) {
  if (i == 4) show_pair();
}
inline void set_design(int d) {
  design = d < 0 ? 0 : (d > 3 ? 3 : d);
  show_layers();
}
inline void set_glance(int slot, int idx) {
  if (slot < 0 || slot > 2) return;
  glance_slot[slot] = idx < 0 ? 0 : (idx >= GLANCE_COUNT ? GLANCE_COUNT - 1 : idx);
  update_info_labels();
}
inline void card_answer(bool yes) {
  (void) yes;
  card_hide();
}
inline uint32_t parse_hex(const std::string &s, uint32_t dflt) {
  if (s.size() != 6) return dflt;
  return (uint32_t) std::strtoul(s.c_str(), nullptr, 16);
}
// pal: "RRGGBB,RRGGBB,RRGGBB" (or "" for Clive's own colours)
inline void card_show_args(const std::string &icon, const std::string &big, const std::string &title, const std::string &sub, const std::string &r1,
                           const std::string &r2, const std::string &r3, int percent, bool ask, const std::string &pal) {
  uint32_t c[3] = {0x5C6BC0, 0xAB47BC, 0x4FD08A};
  size_t a = 0;
  for (int i = 0; i < 3 && a < pal.size(); i++) {
    size_t b = pal.find(',', a);
    if (b == std::string::npos) b = pal.size();
    c[i] = parse_hex(pal.substr(a, b - a), c[i]);
    a = b + 1;
  }
  card_show(icon_by_name(icon), big, title, sub, r1, r2, r3, percent, ask, c[0], c[1], c[2]);
}
// ESPHome does not apply size or position to arc widgets, so the ring design's two arcs are placed here.
inline void place_arc(lv_obj_t *a, int diameter) {
  if (!a) return;
  lv_obj_set_size(a, diameter, diameter);
  lv_obj_align(a, LV_ALIGN_CENTER, 0, 0);
  lv_obj_set_style_bg_opa(a, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(a, 0, 0);
  lv_obj_set_style_pad_all(a, 0, 0);
  lv_obj_remove_flag(a, LV_OBJ_FLAG_SCROLLABLE);
}
inline void init_ui() {
  place_arc(w.ring_sec, (int) (U * 268));
  place_arc(w.ring_hour, (int) (U * 248));
  base_palette();
  for (int i = 0; i < 3; i++) draw_blob_gradient(i, 0.0f);
  hide(w.glow, true);
  hide(w.shade, true);
  hide(w.menu, true);
  hide(w.pair, true);
  update_info_labels();
  show_layers();
}

}  // namespace clive
